using System;
using System.Linq;
using System.Collections.Generic;
using Prometheus;
class ContextTests0255 {
 static int checks; static void Check(bool ok,string name){if(!ok)throw new Exception("FAIL: "+name);checks++;Console.WriteLine("PASS "+name);}
 static Clip Clip(string asset,string stream,string track,string name,double at,double len){return new Clip{id=Store.Id(),asset_id=asset,stream_id=stream,track_id=track,name=name,timeline_start=Rational.Frame(at),duration=Rational.Frame(len),source_in=Rational.Frame(0),speed=new Rational(1,1)};}
 static Editor Make(out string videoTrack,out string audioTrack,out string asset,out string video,out string audio){var e=new Editor();videoTrack=e.Project.Active.tracks.First(t=>t.kind=="video").id;audioTrack=e.Project.Active.tracks.First(t=>t.kind=="audio").id;asset=Store.Id();video=Store.Id();audio=Store.Id();string aid=asset,vid=video,au=audio;e.Commit(p=>{p.assets.Add(new Asset{id=aid,name="fixture",locator=new Locator{path="fixture.mp4"},sha256=new string('a',64),presentation_origin=Rational.Time(0),streams=new List<StreamInfo>{new StreamInfo{id=vid,ordinal=0,kind="video",codec="h264",pts_origin=Rational.Time(0),time_base=new Rational(1,60),duration=Rational.Time(20),nominal_fps=new Rational(60,1)},new StreamInfo{id=au,ordinal=1,kind="audio",codec="aac",pts_origin=Rational.Time(0),time_base=new Rational(1,48000),duration=Rational.Time(20),sample_rate=48000,channels=2}}});});return e;}
 static void Main(){string vt,at,a,v,s;var all=Make(out vt,out at,out a,out v,out s);all.Commit(p=>{p.Active.clips.Add(Clip(a,v,vt,"V",0,8));p.Active.clips.Add(Clip(a,s,at,"A",0,8));});Check(all.RangeTrimSelection(new List<string>(),3,5),"range trim with no selection applies to clips on every track");Store.Validate(all.Project);Check(all.Project.Active.clips.Count==4&&all.Project.Active.clips.All(c=>Math.Abs(c.duration.Seconds-3)<0.02||Math.Abs(c.timeline_start.Seconds-5)<0.02),"all-track range trim preserves both sides and leaves a gap");
 var selected=Make(out vt,out at,out a,out v,out s);selected.Commit(p=>{p.Active.clips.Add(Clip(a,v,vt,"V",0,8));p.Active.clips.Add(Clip(a,s,at,"A",0,8));});string videoId=selected.Project.Active.clips.First(c=>c.track_id==vt).id;Check(selected.RangeTrimSelection(new List<string>{videoId},3,5),"selected range trim executes");Check(selected.Project.Active.clips.Count(c=>c.track_id==vt)==2&&selected.Project.Active.clips.Count(c=>c.track_id==at)==1,"existing selection scopes range trim to selected tracks");
 var linked=Make(out vt,out at,out a,out v,out s);linked.Commit(p=>{p.Active.clips.Add(Clip(a,v,vt,"V",0,8));p.Active.clips.Add(Clip(a,s,at,"A",0,8));p.Active.link_groups.Add(new LinkGroup{id=Store.Id(),clip_ids=p.Active.clips.Select(c=>c.id).ToList()});});videoId=linked.Project.Active.clips.First(c=>c.track_id==vt).id;Check(linked.CutSelection(new List<string>{videoId},4),"cutting a selected linked clip succeeds");Check(linked.Project.Active.clips.Count==4&&linked.Project.Active.link_groups.Count==2,"selected cut also splits linked audio and keeps both linked halves");
 var blocked=Make(out vt,out at,out a,out v,out s);blocked.Commit(p=>{p.Active.clips.Add(Clip(a,v,vt,"V",0,8));p.Active.clips.Add(Clip(a,s,at,"A",0,8));p.Active.tracks.Find(t=>t.id==at).locked=true;});int before=blocked.Project.Active.clips.Count;bool threw=false;try{blocked.RangeTrimSelection(new List<string>(),3,5);}catch{threw=true;}Check(threw&&blocked.Project.Active.clips.Count==before,"range trim refuses locked affected tracks atomically");Console.WriteLine("PASS "+checks+" contextual edit engine checks");}
}
